import re
import numpy as np
from wordfreq import top_n_list, word_frequency

_WORDS = re.compile(r"\b[a-z]+(?:'[a-z]+)?\b")

def _tokenize(text):
    return _WORDS.findall((text or "").lower())

def _bigrams(tokens):
    return [(tokens[i], tokens[i+1]) for i in range(len(tokens) - 1)]

def _high_freq_set():
    """Calibrate on wordfreq top words at import time."""
    return set(top_n_list("en", 3000))

_TOP_FREQ = _high_freq_set()

def formulaic_bigram_cliche(text, anchor):
    tokens = _tokenize(text)
    if len(tokens) < 2:
        return 0.5

    bigrams = _bigrams(tokens)
    if not bigrams:
        return 0.5

    formulaic_count = sum(1 for w1, w2 in bigrams if w1 in _TOP_FREQ and w2 in _TOP_FREQ)
    ratio = formulaic_count / len(bigrams)

    # Invert: high formulaic ratio -> low score (clichéd is bad)
    # Scale range to [0.2, 1.0] to avoid extremes
    score = 0.2 + 0.8 * (1.0 - ratio)
    return max(0.0, min(1.0, score))

METRICS = {"formulaic_bigram_cliche": formulaic_bigram_cliche}

"""Natural Frequency Coherence Scorer"""
import re
import math
import numpy as np
from wordfreq import word_frequency
from difflib import SequenceMatcher
import statistics

def _tokenize(text):
    if not text:
        return []
    pattern = re.compile(r"[a-z]+")
    return pattern.findall(text.lower())

def _freq_bin(word):
    p = word_frequency(word, "en")
    if p == 0:
        return 4
    elif p > 1e-2:
        return 0
    elif p > 1e-3:
        return 1
    elif p > 1e-4:
        return 2
    elif p > 1e-5:
        return 3
    else:
        return 4

def natural_frequency_coherence(text, anchor):
    if not text:
        return 0.5
    tokens = _tokenize(text)
    if len(tokens) < 4:
        return 0.5
    bins = [_freq_bin(tok) for tok in tokens]
    jumps = [abs(bins[i] - bins[i+1]) for i in range(len(bins)-1)]
    large_jumps = sum(1 for j in jumps if j >= 2)
    jump_penalty = large_jumps / len(jumps) if jumps else 0.0
    rare_tokens = sum(1 for b in bins if b >= 3)
    rarity_ratio = rare_tokens / len(bins)
    smoothness_score = 1.0 - min(1.0, jump_penalty * 1.2)
    rarity_score = 1.0 - min(1.0, rarity_ratio * 2.5)
    score = smoothness_score * 0.6 + rarity_score * 0.4
    return max(0.0, min(1.0, score))

METRICS = {"natural_frequency_coherence": natural_frequency_coherence}

"""Anchor Semantic Preservation Scorer"""
import re
import math
import numpy as np
from wordfreq import word_frequency
from difflib import SequenceMatcher
import statistics

def _tokenize(text):
    if not text:
        return []
    pattern = re.compile(r"[a-z]+")
    return pattern.findall(text.lower())

def _stopwords():
    return set(("a an the and or but if then else of to in on at by for with from as is are was were be been being it its this that these those i you he she we they me him her us them my your his their our not no so do does did have has had will would can could should may might must about into over under out up down off than too very just also").split())

def _content_tokens(text):
    toks = _tokenize(text)
    stop = _stopwords()
    return [t for t in toks if t not in stop and len(t) > 1]

def _find_insertions_indices(anchor_tokens, text_tokens):
    matcher = SequenceMatcher(None, anchor_tokens, text_tokens)
    text_matched = set()
    for i, j, size in matcher.get_matching_blocks():
        for k in range(size):
            text_matched.add(j + k)
    return sorted([j for j in range(len(text_tokens)) if j not in text_matched])

def anchor_semantic_preservation(text, anchor):
    if not (text and anchor):
        return 0.5
    anchor_toks = _content_tokens(anchor)
    text_toks = _content_tokens(text)
    if not text_toks or len(anchor_toks) < 2:
        return 0.5
    anchor_freqs = {tok: word_frequency(tok, "en") for tok in anchor_toks}
    core_tokens = set(tok for tok, freq in anchor_freqs.items() if 1e-5 < freq < 1e-2)
    if not core_tokens:
        sorted_toks = sorted(anchor_toks, key=lambda t: word_frequency(t, "en"), reverse=True)
        core_tokens = set(sorted_toks[:max(1, len(sorted_toks)//2)])
    text_set = set(text_toks)
    preserved_fraction = len(core_tokens & text_set) / len(core_tokens)
    if preserved_fraction < 0.3:
        return 0.3
    insertion_indices = _find_insertions_indices(anchor_toks, text_toks)
    if not insertion_indices:
        if preserved_fraction > 0.9:
            return 0.5
        else:
            return 0.4
    new_words = [text_toks[i] for i in insertion_indices]
    new_to_anchor = sum(1 for w in new_words if w not in anchor_toks)
    novelty_ratio = new_to_anchor / len(new_words) if new_words else 0.0
    score = preserved_fraction * 0.7 + novelty_ratio * 0.3
    return max(0.0, min(1.0, score))

METRICS = {"anchor_semantic_preservation": anchor_semantic_preservation}

