from wordfreq import word_frequency
from difflib import SequenceMatcher
import statistics

def _tokenize(text):
    if not text:
        return []
    pattern = re.compile(r"[a-z]+")
    return pattern.findall(text.lower())

def _stopwords():
    return set(("a an the and or but if then else of to in on at by for with from as is are was were be been being it its this that these those i you he she we they me him her us them my your his their our not no so do does did have has had will would can could should may might must about into over under out up down off than too very just also").split())

def _content_tokens(text):
